import{_ as r,l as E,o as e,c as m,v as t,p as o,x as i,d as _,i as l,S as h}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"E₀ 与 E_size","description":"","frontmatter":{"title":"E₀ 与 E_size","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/e0-esize.md","filePath":"litho/e0-esize.md","lastUpdated":1789023840000}'),n={name:"litho/e0-esize.md"};function d(p,a,c,z,A,B){const s=E("Mermaid");return e(),m("div",null,[a[1]||(a[1]=t('<h1 id="e0-与-e-size" tabindex="-1">E₀ 与 E_size <a class="header-anchor" href="#e0-与-e-size" aria-label="Permalink to &quot;E₀ 与 E_size&quot;">​</a></h1><div class="epigraph"><p>$\\gamma$ 是曲线有多陡；$E_0$ 问大垫何时清场，$E_\\mathrm{size}$ 问目标图形何时到尺寸。两个剂量不是一个数的两个名字。</p><footer>—— 据 Mack / Levinson 对 dose-to-clear 与 dose-to-size 的产线定义整理</footer></div><p><a href="/litho/resist-gamma">上一课</a>把 \\(\\gamma\\) 钉在大垫 \\(T(\\log E)\\) 的中段。缺口是曲线上的锚点：产线说「这胶多少剂量」时，有人报清场，有人报到尺寸。本课拆 \\(E_0\\) 与 \\(E_\\mathrm{size}\\)。整条剂量–尺寸曲线，留给<a href="/litho/dose-to-size">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(E_0\\)（dose-to-clear）通常来自开放区或大垫：正胶在给定显影时间下刚好清到底的剂量。它靠近衬度曲线的脚，强烈依赖胶厚、吸收 \\(B\\)、PEB 与显影。\\(E_\\mathrm{size}\\)（dose-to-size）是某一掩模图形、某一照明下，CD 落到目标时的剂量。密线的 \\(E_\\mathrm{size}\\) 往往明显高于 \\(E_0\\)，因为边切在空中像斜坡上，当地强度低于开放区。</p><p>缺口不是再定义 \\(\\gamma\\)，而是：把扫描机配方里的「剂量」默认写成 \\(E_\\mathrm{size}\\)，并把 \\(E_0\\) 留给材料与清底检查。混用会导致「胶更敏了但密线仍印不动」——其实只是 \\(E_0\\) 降了，\\(E_\\mathrm{size}/E_0\\) 没变或更大。</p><h3 id="比值读的是光学-不只是胶" tabindex="-1">比值读的是光学，不只是胶 <a class="header-anchor" href="#比值读的是光学-不只是胶" aria-label="Permalink to &quot;比值读的是光学，不只是胶&quot;">​</a></h3><p>\\(E_\\mathrm{size}/E_0\\) 随 NILS、节距、MEEF 变。光学对比差，要靠加剂量把斜坡抬过化学阈值，比值变大。胶 \\(\\gamma\\) 变陡，比值可以略降，但救不了零级偏置抬死的 \\(I_\\mathrm{min}\\)。不要把这个比值写成胶数据表上的本征常数。</p><p><span class="marginnote">负胶 / NTD 的「清场」语义翻转：开放区可能留下或去掉，视极性而定。写 \\(E_0\\) 必须声明极性与显影液。金属氧化物负胶常用 dose-to-size 签核，开放区剂量含义要另写。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>测 \\(E_0\\)：大垫或开放框剂量矩阵，光学或轮廓仪看残胶。测 \\(E_\\mathrm{size}\\)：目标结构 FEM，CD-SEM 插值到目标 CD。两者必须同一 PEB、同一显影、同一栈。换 BARC 只动 \\(E_\\mathrm{size}\\) 而 \\(E_0\\) 几乎不动，问题在图形光学；两者一起动，问题在吸收或催化。</p><p>LPM 用 \\(E_0\\) 当集总锚，再用空中像把边推到 \\(E_\\mathrm{size}\\)。标定顺序不能反：先拿密线 \\(E_\\mathrm{size}\\) 当 \\(E_0\\)，薄膜一改就全部漂。</p>',12)),(e(),o(h,null,{default:i(()=>[l(s,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20PAD%5B%22%E5%A4%A7%E5%9E%AB%20%2F%20%E5%BC%80%E6%94%BE%E5%8C%BA%22%5D%20--%3E%20E0%5B%22E0%20%E6%B8%85%E5%9C%BA%22%5D%0A%20%20FEAT%5B%22%E7%9B%AE%E6%A0%87%E5%9B%BE%E5%BD%A2%20%2B%20%E7%85%A7%E6%98%8E%22%5D%20--%3E%20ES%5B%22E_size%20%E5%88%B0%E5%B0%BA%E5%AF%B8%22%5D%0A%20%20E0%20--%3E%20RATIO%5B%22E_size%20%2F%20E0%22%5D%0A%20%20ES%20--%3E%20RATIO%0A%20%20NILS%5B%22NILS%20%2F%20%E8%8A%82%E8%B7%9D%22%5D%20--%3E%20RATIO%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[_(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>开放区强度接近空中像的局部最大（还含 flare）。清底要求沿厚的有效剂量把 \\(m\\) 降到 \\(R\\) 能挖穿。图形边的强度是 \\(I_\\mathrm{th}\\lt I_\\mathrm{max}\\)，要让 \\(I_\\mathrm{th}\\) 对应的化学达到同样的 \\(m\\) 阈值，入射剂量必须更高——于是 \\(E_\\mathrm{size}\\gt E_0\\)。flare 抬暗区，会抬 \\(E_0\\) 的「起雾」端，却不一定按同一比例抬 \\(E_\\mathrm{size}\\)，暗侵蚀与桥接先报警。</p><p>淬灭剂负载同时抬两个锚点，但 \\(E_\\mathrm{size}\\) 对负载往往更敏感，因为边沿正在争夺带上。<a href="/litho/pag-quencher">淬灭剂</a>的阈值语言在这里变成两个可测剂量。</p><p><span class="marginnote">\\(E_0\\) 有时被定义为「开始掉厚」而不是「清底」，教材不统一。对表写清。本课默认正胶清底，除非声明。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不把某胶说明书上的 15 mJ/cm² 写成所有节距的 \\(E_\\mathrm{size}\\)。不重推瑞利公式来「预言」两个剂量。下一课把 \\(E_\\mathrm{size}\\) 从单点展开成 CD(E) 曲线。</p><p>EUV 随机效应里，平均 \\(E_\\mathrm{size}\\) 合格仍可能缺孔——那是后一单元；本课两个锚点仍是均值。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>\\(E_0\\) 是大垫清场；\\(E_\\mathrm{size}\\) 是目标图形到尺寸。</li><li>扫描配方默认 \\(E_\\mathrm{size}\\)；材料比较常报 \\(E_0\\)。</li><li>\\(E_\\mathrm{size}/E_0\\) 主要读光学对比与节距，不是胶的本征常数。</li><li>两者必须同栈、同 PEB 测。</li><li>出处：Mack / Levinson 对 dose-to-clear 与 dose-to-size。</li></ul>',9))])}const T=r(n,[["render",d]]);export{u as __pageData,T as default};
